BEGIN;
SELECT pg_advisory_xact_lock(hashtext('cyberlearnix.demo-course-catalog.v1'));

DO $seed$
BEGIN
    IF EXISTS (
        SELECT title FROM courses
        WHERE title IN ('Java Backend Development: Spring Boot and Microservices', 'Python Full-Stack Development with Django and React', 'Cybersecurity Fundamentals: Defense, Detection, and Response', 'Data Structures and Algorithms in Java', 'Cloud and DevOps Engineering with AWS and Kubernetes')
        GROUP BY title HAVING COUNT(*) > 1
    ) THEN
        RAISE EXCEPTION 'Duplicate managed course titles exist; resolve them before seeding';
    END IF;
    IF EXISTS (
        SELECT 1 FROM courses
        WHERE (title = 'Java Backend Development: Spring Boot and Microservices' AND (category IS DISTINCT FROM 'Software Engineering' OR instructor_id IS DISTINCT FROM 'd2100000-0000-0000-0000-000000000001'::uuid OR status IS DISTINCT FROM 'PUBLISHED'))
           OR (title = 'Python Full-Stack Development with Django and React' AND (category IS DISTINCT FROM 'Software Engineering' OR instructor_id IS DISTINCT FROM 'd2100000-0000-0000-0000-000000000002'::uuid OR status IS DISTINCT FROM 'PUBLISHED'))
           OR (title = 'Cybersecurity Fundamentals: Defense, Detection, and Response' AND (category IS DISTINCT FROM 'Cybersecurity' OR instructor_id IS DISTINCT FROM 'd2100000-0000-0000-0000-000000000003'::uuid OR status IS DISTINCT FROM 'PUBLISHED'))
           OR (title = 'Data Structures and Algorithms in Java' AND (category IS DISTINCT FROM 'Computer Science' OR instructor_id IS DISTINCT FROM 'd2100000-0000-0000-0000-000000000004'::uuid OR status IS DISTINCT FROM 'PUBLISHED'))
           OR (title = 'Cloud and DevOps Engineering with AWS and Kubernetes' AND (category IS DISTINCT FROM 'Cloud and DevOps' OR instructor_id IS DISTINCT FROM 'd2100000-0000-0000-0000-000000000005'::uuid OR status IS DISTINCT FROM 'PUBLISHED'))
    ) THEN
        RAISE EXCEPTION 'A managed course title has conflicting parent data; no rows were changed';
    END IF;
END
$seed$;

INSERT INTO courses (title, subtitle, description, category, level, language, price, thumbnail, instructor_id, status, premium, search_count, view_count)
SELECT seed.title, seed.subtitle, seed.description, seed.category, seed.level, 'English', seed.price, seed.thumbnail, seed.instructor_id, 'PUBLISHED', seed.premium, 0, 0
FROM (VALUES
    ('Java Backend Development: Spring Boot and Microservices', 'Build secure Java services from fundamentals to deployment', 'Build a tested REST service, persist data with PostgreSQL, secure APIs with Spring Security and JWT, then split a monolith into observable services with Docker and Kafka.', 'Software Engineering', 'INTERMEDIATE', 4999.00, 'https://images.unsplash.com/photo-1517694712202-14dd9538aa97?auto=format&fit=crop&w=1400&q=85', 'd2100000-0000-0000-0000-000000000001'::uuid, TRUE),
    ('Python Full-Stack Development with Django and React', 'Create a web product with a Django API and a responsive React client', 'Model relational data, design a versioned REST API, build accessible React screens, add authentication and automated tests, and package the service for a repeatable release.', 'Software Engineering', 'INTERMEDIATE', 4299.00, 'https://images.unsplash.com/photo-1526379095098-d400fd0bf935?auto=format&fit=crop&w=1400&q=85', 'd2100000-0000-0000-0000-000000000002'::uuid, TRUE),
    ('Cybersecurity Fundamentals: Defense, Detection, and Response', 'Practical security judgment across networks, applications, and incident response', 'Establish a threat model, inspect network traffic, apply secure identity and application patterns, investigate suspicious activity, and present an incident response plan using established guidance.', 'Cybersecurity', 'BEGINNER', 3499.00, 'https://images.unsplash.com/photo-1550751827-4bd374c3f58b?auto=format&fit=crop&w=1400&q=85', 'd2100000-0000-0000-0000-000000000003'::uuid, FALSE),
    ('Data Structures and Algorithms in Java', 'Choose data structures and explain the trade-offs behind each solution', 'Progress through complexity analysis, core data structures, trees, graphs, and algorithm design. Turn common interview patterns into tested Java implementations and reasoned complexity analysis.', 'Computer Science', 'INTERMEDIATE', 2999.00, 'https://images.unsplash.com/photo-1515879218367-8466d910aaa4?auto=format&fit=crop&w=1400&q=85', 'd2100000-0000-0000-0000-000000000004'::uuid, FALSE),
    ('Cloud and DevOps Engineering with AWS and Kubernetes', 'Automate delivery and operate resilient container workloads in the cloud', 'Build and scan container images, deploy workloads to Kubernetes, provision infrastructure with Terraform, and use metrics, logs, and recovery practices to improve reliability.', 'Cloud and DevOps', 'INTERMEDIATE', 5499.00, 'https://images.unsplash.com/photo-1667372393119-3d4c48d07fc9?auto=format&fit=crop&w=1400&q=85', 'd2100000-0000-0000-0000-000000000005'::uuid, TRUE)
) AS seed(title, subtitle, description, category, level, price, thumbnail, instructor_id, premium)
WHERE NOT EXISTS (SELECT 1 FROM courses existing WHERE existing.title = seed.title);

INSERT INTO sections (course_id, title, order_index)
SELECT c.id, seed.section_title, seed.order_index
FROM (VALUES
('Java Backend Development: Spring Boot and Microservices','Java language foundations',1),('Java Backend Development: Spring Boot and Microservices','Object-oriented design and exceptions',2),('Java Backend Development: Spring Boot and Microservices','Collections, streams, and testing',3),('Java Backend Development: Spring Boot and Microservices','PostgreSQL persistence and REST APIs',4),('Java Backend Development: Spring Boot and Microservices','Security and distributed services',5),
('Python Full-Stack Development with Django and React','Python foundations for web development',1),('Python Full-Stack Development with Django and React','Django models, views, and templates',2),('Python Full-Stack Development with Django and React','REST APIs and PostgreSQL',3),('Python Full-Stack Development with Django and React','React client and end-to-end testing',4),('Python Full-Stack Development with Django and React','Production deployment and operations',5),
('Cybersecurity Fundamentals: Defense, Detection, and Response','Security principles and threat modeling',1),('Cybersecurity Fundamentals: Defense, Detection, and Response','Network visibility and defense',2),('Cybersecurity Fundamentals: Defense, Detection, and Response','Identity and application security',3),('Cybersecurity Fundamentals: Defense, Detection, and Response','Detection and incident response',4),('Cybersecurity Fundamentals: Defense, Detection, and Response','Cloud controls and security assessment',5),
('Data Structures and Algorithms in Java','Problem solving and complexity',1),('Data Structures and Algorithms in Java','Linear structures and hash-based lookup',2),('Data Structures and Algorithms in Java','Trees, heaps, and graph models',3),('Data Structures and Algorithms in Java','Searching, sorting, and optimization',4),('Data Structures and Algorithms in Java','Interview patterns and capstone',5),
('Cloud and DevOps Engineering with AWS and Kubernetes','Linux, Git, and delivery foundations',1),('Cloud and DevOps Engineering with AWS and Kubernetes','Container images and local orchestration',2),('Cloud and DevOps Engineering with AWS and Kubernetes','Kubernetes workloads and configuration',3),('Cloud and DevOps Engineering with AWS and Kubernetes','CI/CD and infrastructure as code',4),('Cloud and DevOps Engineering with AWS and Kubernetes','Observability and resilient operations',5)
) AS seed(course_title, section_title, order_index)
JOIN courses c ON c.title=seed.course_title
WHERE NOT EXISTS (SELECT 1 FROM sections e WHERE e.course_id=c.id AND e.title=seed.section_title);

INSERT INTO lectures (section_id, title, description, video_url, duration, order_index, preview_enabled, resources, type)
SELECT s.id, seed.lecture_title, seed.description, NULL, seed.duration, seed.order_index, seed.preview_enabled, seed.resources, seed.lecture_type
FROM (VALUES
('Java Backend Development: Spring Boot and Microservices','Java language foundations','Set up a reproducible Java workspace','Install a JDK, configure an IDE, and run a project from the command line.',12,1,TRUE,'https://dev.java/learn/','ARTICLE'),('Java Backend Development: Spring Boot and Microservices','Java language foundations','Model values, control flow, and methods','Use types, branch safely, and decompose behavior into focused methods.',16,2,FALSE,'https://dev.java/learn/language-basics/','ARTICLE'),('Java Backend Development: Spring Boot and Microservices','Java language foundations','Work with records, enums, and packages','Organize domain values and keep package boundaries understandable.',14,3,FALSE,'https://docs.oracle.com/en/java/javase/21/docs/api/','DOCUMENT'),('Java Backend Development: Spring Boot and Microservices','Java language foundations','Test a command-line program','Parse input, report errors clearly, and test the program contract.',18,4,FALSE,'https://junit.org/junit5/docs/current/user-guide/','ARTICLE'),
('Java Backend Development: Spring Boot and Microservices','Object-oriented design and exceptions','Design cohesive classes and constructors','Give each class a clear responsibility and keep invalid state out of constructors.',17,1,TRUE,'https://dev.java/learn/classes-objects/','ARTICLE'),('Java Backend Development: Spring Boot and Microservices','Object-oriented design and exceptions','Use interfaces and composition','Model replaceable behavior and avoid inheritance that adds coupling.',18,2,FALSE,'https://dev.java/learn/interfaces/','ARTICLE'),('Java Backend Development: Spring Boot and Microservices','Object-oriented design and exceptions','Handle failures with domain exceptions','Distinguish recoverable input errors from infrastructure failures.',15,3,FALSE,'https://docs.oracle.com/javase/tutorial/essential/exceptions/','ARTICLE'),('Java Backend Development: Spring Boot and Microservices','Object-oriented design and exceptions','Refactor around a testable service boundary','Extract a focused contract and verify it with unit tests.',20,4,FALSE,'https://junit.org/junit5/docs/current/user-guide/','DOCUMENT'),
('Java Backend Development: Spring Boot and Microservices','Collections, streams, and testing','Choose collections by access pattern','Compare lists, sets, and maps using ordering, uniqueness, and lookup needs.',15,1,TRUE,'https://docs.oracle.com/en/java/javase/21/docs/api/java.base/java/util/package-summary.html','DOCUMENT'),('Java Backend Development: Spring Boot and Microservices','Collections, streams, and testing','Use generics without unsafe casts','Express reusable APIs with bounded type parameters and wildcard variance.',17,2,FALSE,'https://dev.java/learn/generics/','ARTICLE'),('Java Backend Development: Spring Boot and Microservices','Collections, streams, and testing','Transform data with streams','Compose filtering, mapping, grouping, and reduction in readable pipelines.',19,3,FALSE,'https://dev.java/learn/api/streams/','ARTICLE'),('Java Backend Development: Spring Boot and Microservices','Collections, streams, and testing','Test edge cases and collection contracts','Use parameterized tests and meaningful assertions to protect transformations.',18,4,FALSE,'https://junit.org/junit5/docs/current/user-guide/','DOCUMENT'),
('Java Backend Development: Spring Boot and Microservices','PostgreSQL persistence and REST APIs','Connect Spring Boot to PostgreSQL','Configure a datasource and separate connection settings from application code.',20,1,TRUE,'https://docs.spring.io/spring-boot/reference/data/sql.html','ARTICLE'),('Java Backend Development: Spring Boot and Microservices','PostgreSQL persistence and REST APIs','Map entities and transaction boundaries','Persist an aggregate with JPA and choose transactions around business operations.',22,2,FALSE,'https://docs.spring.io/spring-data/jpa/reference/','DOCUMENT'),('Java Backend Development: Spring Boot and Microservices','PostgreSQL persistence and REST APIs','Build a validated REST resource','Apply Bean Validation and return meaningful HTTP statuses.',21,3,FALSE,'https://spring.io/guides/gs/rest-service','ARTICLE'),('Java Backend Development: Spring Boot and Microservices','PostgreSQL persistence and REST APIs','Paginate a course catalog','Design stable pagination and filters for a relational catalog.',19,4,FALSE,'https://docs.spring.io/spring-data/commons/reference/','DOCUMENT'),
('Java Backend Development: Spring Boot and Microservices','Security and distributed services','Apply Spring Security to routes','Separate public reads from authenticated authoring and administrative actions.',21,1,TRUE,'https://docs.spring.io/spring-security/reference/','DOCUMENT'),('Java Backend Development: Spring Boot and Microservices','Security and distributed services','Validate JWT claims and authorization','Check issuer, audience, expiry, and authorities before protected operations.',20,2,FALSE,'https://docs.spring.io/spring-security/reference/servlet/oauth2/resource-server/jwt.html','ARTICLE'),('Java Backend Development: Spring Boot and Microservices','Security and distributed services','Define service boundaries and resilience','Set explicit timeout and retry behavior around service dependencies.',22,3,FALSE,'https://resilience4j.readme.io/docs','DOCUMENT'),('Java Backend Development: Spring Boot and Microservices','Security and distributed services','Package a service with Docker and Kafka','Build a repeatable image and use an event contract for asynchronous work.',24,4,FALSE,'https://docs.docker.com/','ARTICLE'),
('Python Full-Stack Development with Django and React','Python foundations for web development','Create a virtual environment and project','Pin dependencies, isolate the interpreter, and establish a clean layout.',12,1,TRUE,'https://docs.python.org/3/tutorial/venv.html','ARTICLE'),('Python Full-Stack Development with Django and React','Python foundations for web development','Use Python collections and comprehensions','Select suitable structures and write transformations that remain readable.',17,2,FALSE,'https://docs.python.org/3/tutorial/datastructures.html','ARTICLE'),('Python Full-Stack Development with Django and React','Python foundations for web development','Structure functions, modules, and exceptions','Keep modules cohesive and turn low-level failures into clear errors.',16,3,FALSE,'https://docs.python.org/3/tutorial/modules.html','DOCUMENT'),('Python Full-Stack Development with Django and React','Python foundations for web development','Test a domain service with pytest','Cover normal, boundary, and invalid input before building the web layer.',18,4,FALSE,'https://docs.pytest.org/en/stable/getting-started.html','ARTICLE'),
