('Cloud and DevOps Engineering with AWS and Kubernetes','Linux, Git, and delivery foundations','Navigate Linux processes and filesystems','Inspect processes, permissions, logs, and resource use from the command line.',15,1,TRUE,'https://linuxjourney.com/','ARTICLE'),('Cloud and DevOps Engineering with AWS and Kubernetes','Linux, Git, and delivery foundations','Build a reviewable Git workflow','Use focused commits, pull-request checks, and branch protection.',16,2,FALSE,'https://git-scm.com/docs','DOCUMENT'),('Cloud and DevOps Engineering with AWS and Kubernetes','Linux, Git, and delivery foundations','Automate a repeatable operational task','Create a script with clear inputs, exit codes, and safe failure behavior.',18,3,FALSE,'https://www.gnu.org/software/bash/manual/','ARTICLE'),('Cloud and DevOps Engineering with AWS and Kubernetes','Linux, Git, and delivery foundations','Define service health and release criteria','Translate service objectives into deploy checks and rollback decisions.',17,4,FALSE,'https://sre.google/sre-book/monitoring-distributed-systems/','DOCUMENT'),
('Cloud and DevOps Engineering with AWS and Kubernetes','Container images and local orchestration','Write a reproducible Dockerfile','Use a minimal base image, explicit dependencies, and a non-root runtime user.',18,1,TRUE,'https://docs.docker.com/build/building/best-practices/','ARTICLE'),('Cloud and DevOps Engineering with AWS and Kubernetes','Container images and local orchestration','Manage image layers and build cache','Order build steps for useful caching and scan images before publication.',16,2,FALSE,'https://docs.docker.com/build/cache/','DOCUMENT'),('Cloud and DevOps Engineering with AWS and Kubernetes','Container images and local orchestration','Connect services with Compose','Describe a local stack with dependencies and health checks.',19,3,FALSE,'https://docs.docker.com/compose/','ARTICLE'),('Cloud and DevOps Engineering with AWS and Kubernetes','Container images and local orchestration','Keep secrets out of images and logs','Inject credentials through runtime configuration, not image layers.',17,4,FALSE,'https://docs.docker.com/engine/swarm/secrets/','DOCUMENT'),
('Cloud and DevOps Engineering with AWS and Kubernetes','Kubernetes workloads and configuration','Deploy a workload with health probes','Set resource requests and probes so orchestration can make informed decisions.',20,1,TRUE,'https://kubernetes.io/docs/concepts/workloads/controllers/deployment/','ARTICLE'),('Cloud and DevOps Engineering with AWS and Kubernetes','Kubernetes workloads and configuration','Expose a service with stable discovery','Choose service types and understand how traffic reaches a healthy pod.',18,2,FALSE,'https://kubernetes.io/docs/concepts/services-networking/service/','DOCUMENT'),('Cloud and DevOps Engineering with AWS and Kubernetes','Kubernetes workloads and configuration','Configure workloads without rebuilding images','Use ConfigMaps and Secrets with appropriate access and rotation practices.',18,3,FALSE,'https://kubernetes.io/docs/concepts/configuration/','ARTICLE'),('Cloud and DevOps Engineering with AWS and Kubernetes','Kubernetes workloads and configuration','Package environment differences with Helm','Parameterize deployment configuration while keeping defaults reviewable.',20,4,FALSE,'https://helm.sh/docs/','DOCUMENT'),
('Cloud and DevOps Engineering with AWS and Kubernetes','CI/CD and infrastructure as code','Create a tested GitHub Actions workflow','Run build and test checks on pull requests with least-privilege permissions.',18,1,TRUE,'https://docs.github.com/en/actions','ARTICLE'),('Cloud and DevOps Engineering with AWS and Kubernetes','CI/CD and infrastructure as code','Provision resources with Terraform','Declare reusable infrastructure and review planned changes before applying.',21,2,FALSE,'https://developer.hashicorp.com/terraform/docs','DOCUMENT'),('Cloud and DevOps Engineering with AWS and Kubernetes','CI/CD and infrastructure as code','Promote artifacts through environments','Deploy the same immutable artifact with external configuration.',18,3,FALSE,'https://docs.github.com/en/actions/deployment/about-deployments','ARTICLE'),('Cloud and DevOps Engineering with AWS and Kubernetes','CI/CD and infrastructure as code','Add dependency and image security checks','Surface findings early and document exceptions with owners and expiry.',19,4,FALSE,'https://docs.github.com/en/code-security','DOCUMENT'),
('Cloud and DevOps Engineering with AWS and Kubernetes','Observability and resilient operations','Instrument useful service metrics','Choose signals for latency, traffic, errors, and saturation.',19,1,TRUE,'https://opentelemetry.io/docs/','ARTICLE'),('Cloud and DevOps Engineering with AWS and Kubernetes','Observability and resilient operations','Correlate logs, metrics, and traces','Use consistent context to move from an alert to the affected request path.',20,2,FALSE,'https://opentelemetry.io/docs/concepts/observability-primer/','DOCUMENT'),('Cloud and DevOps Engineering with AWS and Kubernetes','Observability and resilient operations','Practice safe rollback and recovery','Define recovery steps and validate them with a controlled failure scenario.',18,3,FALSE,'https://sre.google/sre-book/handling-overload/','ARTICLE'),('Cloud and DevOps Engineering with AWS and Kubernetes','Observability and resilient operations','Deliver a cloud operations capstone','Document architecture, delivery, service signals, and recovery steps.',25,4,FALSE,'https://docs.aws.amazon.com/wellarchitected/latest/framework/welcome.html','DOCUMENT')
) AS seed(course_title, section_title, lecture_title, description, duration, order_index, preview_enabled, resources, lecture_type)
JOIN courses c ON c.title=seed.course_title
JOIN sections s ON s.course_id=c.id AND s.title=seed.section_title
WHERE NOT EXISTS (SELECT 1 FROM lectures e WHERE e.section_id=s.id AND e.title=seed.lecture_title);

INSERT INTO course_requirements (course_id, requirement_type, requirement_text, created_at)
SELECT c.id, seed.requirement_type, seed.requirement_text, CURRENT_TIMESTAMP
FROM (VALUES
('Java Backend Development: Spring Boot and Microservices','PRIOR_KNOWLEDGE','Comfort with programming concepts such as variables, conditionals, and functions.'),('Java Backend Development: Spring Boot and Microservices','SOFTWARE','A current JDK, an IDE, Git, and PostgreSQL are used in the exercises.'),('Java Backend Development: Spring Boot and Microservices','TIME_COMMITMENT','Plan for approximately four hours of study and implementation per week.'),
('Python Full-Stack Development with Django and React','PRIOR_KNOWLEDGE','Basic programming experience and familiarity with a command line are recommended.'),('Python Full-Stack Development with Django and React','SOFTWARE','Python 3, Node.js, Git, and PostgreSQL are used in the project exercises.'),('Python Full-Stack Development with Django and React','TIME_COMMITMENT','Plan for approximately five hours per week to complete the application milestones.'),
('Cybersecurity Fundamentals: Defense, Detection, and Response','PRIOR_KNOWLEDGE','No professional security background is required; basic computer and network use is helpful.'),('Cybersecurity Fundamentals: Defense, Detection, and Response','SOFTWARE','Use isolated labs and supplied captures; do not test public systems.'),('Cybersecurity Fundamentals: Defense, Detection, and Response','TIME_COMMITMENT','Plan for approximately three hours per week, including the response exercise.'),
('Data Structures and Algorithms in Java','PRIOR_KNOWLEDGE','Write basic Java programs and understand methods, arrays, and object references.'),('Data Structures and Algorithms in Java','SOFTWARE','A JDK, Java editor, and a test runner such as JUnit are recommended.'),('Data Structures and Algorithms in Java','TIME_COMMITMENT','Plan for four to five hours per week for implementation and analysis.'),
('Cloud and DevOps Engineering with AWS and Kubernetes','PRIOR_KNOWLEDGE','Basic Linux command-line use, Git, and familiarity with HTTP services are recommended.'),('Cloud and DevOps Engineering with AWS and Kubernetes','SOFTWARE','Docker, kubectl, Terraform, and a local Kubernetes option are used in labs.'),('Cloud and DevOps Engineering with AWS and Kubernetes','TIME_COMMITMENT','Plan for five hours per week; optional cloud-account usage may incur provider charges.')
) AS seed(course_title, requirement_type, requirement_text)
JOIN courses c ON c.title=seed.course_title
WHERE NOT EXISTS (SELECT 1 FROM course_requirements e WHERE e.course_id=c.id AND e.requirement_type=seed.requirement_type AND e.requirement_text=seed.requirement_text);

INSERT INTO learning_outcomes (course_id, outcome_text, skill_category, created_at)
SELECT c.id, seed.outcome_text, seed.skill_category, CURRENT_TIMESTAMP
FROM (VALUES
('Java Backend Development: Spring Boot and Microservices','Build a validated REST API with Spring Boot and clear request contracts.','TECHNICAL'),('Java Backend Development: Spring Boot and Microservices','Persist relational data with PostgreSQL and deliberate transaction boundaries.','TECHNICAL'),('Java Backend Development: Spring Boot and Microservices','Secure endpoints with role-aware authorization and verified JWT claims.','INDUSTRY_SPECIFIC'),('Java Backend Development: Spring Boot and Microservices','Explain service boundaries, failure handling, and deployment trade-offs.','SOFT_SKILLS'),
('Python Full-Stack Development with Django and React','Model a relational domain and expose it through a validated Django REST API.','TECHNICAL'),('Python Full-Stack Development with Django and React','Build responsive React workflows with explicit loading and error states.','TECHNICAL'),('Python Full-Stack Development with Django and React','Test API contracts and user journeys before release.','INDUSTRY_SPECIFIC'),('Python Full-Stack Development with Django and React','Deliver a documented full-stack application with repeatable deployment steps.','SOFT_SKILLS'),
('Cybersecurity Fundamentals: Defense, Detection, and Response','Create a threat model that records trust boundaries and assumptions.','TECHNICAL'),('Cybersecurity Fundamentals: Defense, Detection, and Response','Interpret network and application evidence using a safe lab.','TECHNICAL'),('Cybersecurity Fundamentals: Defense, Detection, and Response','Prioritize findings and map mitigations to recognized guidance.','INDUSTRY_SPECIFIC'),('Cybersecurity Fundamentals: Defense, Detection, and Response','Write an incident timeline, impact summary, and recovery plan.','SOFT_SKILLS'),
('Data Structures and Algorithms in Java','Select data structures based on access patterns and constraints.','TECHNICAL'),('Data Structures and Algorithms in Java','Implement and test tree, graph, search, and optimization algorithms in Java.','TECHNICAL'),('Data Structures and Algorithms in Java','Analyze correctness, time complexity, and space complexity.','INDUSTRY_SPECIFIC'),('Data Structures and Algorithms in Java','Communicate algorithm choices and edge-case reasoning clearly.','SOFT_SKILLS'),
('Cloud and DevOps Engineering with AWS and Kubernetes','Build reproducible container images and deploy workloads with health checks.','TECHNICAL'),('Cloud and DevOps Engineering with AWS and Kubernetes','Automate build, test, and infrastructure workflows with reviewed changes.','TECHNICAL'),('Cloud and DevOps Engineering with AWS and Kubernetes','Use service metrics, logs, and traces to investigate operational issues.','INDUSTRY_SPECIFIC'),('Cloud and DevOps Engineering with AWS and Kubernetes','Document release, rollback, and recovery procedures for a cloud service.','SOFT_SKILLS')
) AS seed(course_title, outcome_text, skill_category)
JOIN courses c ON c.title=seed.course_title
WHERE NOT EXISTS (SELECT 1 FROM learning_outcomes e WHERE e.course_id=c.id AND e.outcome_text=seed.outcome_text);

INSERT INTO course_materials (course_id, material_name, material_type, file_url, created_at)
SELECT c.id, seed.material_name, 'LINK', seed.file_url, CURRENT_TIMESTAMP
FROM (VALUES
('Java Backend Development: Spring Boot and Microservices','Java language and API reference','https://dev.java/learn/'),('Java Backend Development: Spring Boot and Microservices','Spring Boot reference documentation','https://docs.spring.io/spring-boot/reference/'),
('Python Full-Stack Development with Django and React','Python language tutorial','https://docs.python.org/3/tutorial/'),('Python Full-Stack Development with Django and React','Django REST Framework guide','https://www.django-rest-framework.org/'),
('Cybersecurity Fundamentals: Defense, Detection, and Response','OWASP Top Ten reference','https://owasp.org/www-project-top-ten/'),('Cybersecurity Fundamentals: Defense, Detection, and Response','NIST incident response guidance','https://csrc.nist.gov/pubs/sp/800/61/r2/final'),
('Data Structures and Algorithms in Java','Algorithms reference and worked examples','https://cp-algorithms.com/'),('Data Structures and Algorithms in Java','Algorithm visualization exercises','https://visualgo.net/en'),
('Cloud and DevOps Engineering with AWS and Kubernetes','Kubernetes documentation and tutorials','https://kubernetes.io/docs/home/'),('Cloud and DevOps Engineering with AWS and Kubernetes','Docker build and operations guides','https://docs.docker.com/')
) AS seed(course_title, material_name, file_url)
JOIN courses c ON c.title=seed.course_title
WHERE NOT EXISTS (SELECT 1 FROM course_materials e WHERE e.course_id=c.id AND e.material_name=seed.material_name);

INSERT INTO course_faq (course_id, question, answer, display_order, created_at)
SELECT c.id, seed.question, seed.answer, seed.display_order, CURRENT_TIMESTAMP
FROM (VALUES
('Java Backend Development: Spring Boot and Microservices','Do I need prior Spring experience?','No. The course starts with Java foundations and introduces Spring through the project.',1),('Python Full-Stack Development with Django and React','Do I need to know React before starting?','No. Basic programming experience is helpful; the client modules introduce React step by step.',1),('Cybersecurity Fundamentals: Defense, Detection, and Response','Is testing performed on public targets?','No. Practical activities use supplied material and isolated lab environments only.',1),('Data Structures and Algorithms in Java','Should I already know Java?','Yes. You should be able to write basic Java programs and use arrays and methods.',1),('Cloud and DevOps Engineering with AWS and Kubernetes','Are cloud provider charges included?','No. Optional cloud-account or resource charges are controlled by the learner and provider.',1)
) AS seed(course_title, question, answer, display_order)
JOIN courses c ON c.title=seed.course_title
WHERE NOT EXISTS (SELECT 1 FROM course_faq e WHERE e.course_id=c.id AND e.question=seed.question);

SELECT 'managed course rows' AS verification, COUNT(*) AS course_count
FROM courses
WHERE title IN ('Java Backend Development: Spring Boot and Microservices', 'Python Full-Stack Development with Django and React', 'Cybersecurity Fundamentals: Defense, Detection, and Response', 'Data Structures and Algorithms in Java', 'Cloud and DevOps Engineering with AWS and Kubernetes');
COMMIT;